import React, { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import {
  GoogleMap,
  Marker,
  DirectionsRenderer,
  useJsApiLoader
} from "@react-google-maps/api";

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";
const GOOGLE_MAPS_API_KEY = process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "";

const containerStyle = {
  width: "100%",
  height: "600px",
};

const defaultCenter = {
  lat: 6.9271, // Colombo fallback
  lng: 79.8612,
};

export default function DeliveryTracking() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const mapRef = useRef<google.maps.Map | null>(null);

  // State
  const [driverAddress, setDriverAddress] = useState<string>("");
  const [deliveryAddress, setDeliveryAddress] = useState<string>("");
  const [driverLocation, setDriverLocation] = useState<google.maps.LatLngLiteral | null>(null);
  const [destination, setDestination] = useState<google.maps.LatLngLiteral | null>(null);
  const [directions, setDirections] = useState<google.maps.DirectionsResult | null>(null);
  const [distanceText, setDistanceText] = useState<string>("");
  const [durationText, setDurationText] = useState<string>("");

  const { isLoaded } = useJsApiLoader({
    googleMapsApiKey: GOOGLE_MAPS_API_KEY,
    libraries: ["places"]
  });

  // 1. Fetch delivery & driver data
  useEffect(() => {
    if (!id) return;

    (async () => {
      try {
        // Fetch delivery
        const delRes = await axios.get(`${API_BASE_URL}/api/delivery/${id}`);
        const delivery = delRes.data;
        setDeliveryAddress(delivery.address);
        setDestination(delivery.location);

        // Fetch driver details
        const drvRes = await axios.get(`${API_BASE_URL}/api/drivers/${delivery.driverId}`);
        const driver = drvRes.data;
        setDriverAddress(driver.address);

        // Geocode driver address for initial marker
        const geoRes = await axios.get(
          `https://maps.googleapis.com/maps/api/geocode/json`,
          {
            params: {
              address: driver.address,
              key: GOOGLE_MAPS_API_KEY
            }
          }
        );
        const driverLoc = geoRes.data.results[0].geometry.location;
        setDriverLocation({
          lat: driverLoc.lat,
          lng: driverLoc.lng
        });
      } catch (err) {
        console.error("Error fetching data:", err);
      }
    })();
  }, [id, GOOGLE_MAPS_API_KEY]);

  // 2. When both points exist, request directions
  useEffect(() => {
    if (!driverLocation || !destination || !isLoaded) return;

    const service = new google.maps.DirectionsService();
    service.route(
      {
        origin: driverLocation,
        destination,
        travelMode: google.maps.TravelMode.DRIVING,
      },
      (result, status) => {
        if (status === "OK" && result) {
          setDirections(result);

          // Extract distance & duration from first leg
          const leg = result.routes[0].legs[0];
          setDistanceText(leg.distance?.text || "");
          setDurationText(leg.duration?.text || "");
        } else {
          console.error("Directions request failed:", status);
        }
      }
    );
  }, [driverLocation, destination, isLoaded]);

  if (!isLoaded) return <div>Loading map...</div>;

  return (
    <div style={{ padding: "20px" }}>
      <h2>🚚 Delivery Tracking</h2>

      <button
        onClick={() => navigate(-1)}
        style={{
          marginBottom: "10px",
          padding: "8px 16px",
          background: "#6c757d",
          color: "#fff",
          border: "none",
          borderRadius: "4px",
          cursor: "pointer",
        }}
      >
        ← Back
      </button>

      <div style={{ marginBottom: "16px" }}>
        <p><strong>Driver Address:</strong> {driverAddress}</p>
        <p><strong>Delivery Address:</strong> {deliveryAddress}</p>
        <p><strong>Distance:</strong> {distanceText} &nbsp; <strong>ETA:</strong> {durationText}</p>
      </div>

      <GoogleMap
        mapContainerStyle={containerStyle}
        center={driverLocation || destination || defaultCenter}
        zoom={12}
        onLoad={(map) => (mapRef.current = map)}
      >
        {driverLocation && (
          <Marker
            position={driverLocation}
            label="🚚"
          />
        )}

        {destination && (
          <Marker
            position={destination}
            label="📍"
          />
        )}

        {directions && (
          <DirectionsRenderer
            directions={directions}
            options={{ suppressMarkers: true }}
          />
        )}
      </GoogleMap>
    </div>
  );
}
